import React from 'react';
import './HierarchicalRenderer.css';

/**
 * Simple hierarchical renderer for Containable objects (DeploymentUnits and ComponentFolders)
 * Uses recursive rendering to display nested structures
 */
const HierarchicalRenderer = ({ data }) => {
  
  // Debug logging
  console.log('HierarchicalRenderer received data:', data);
  
  return (
    <div style={{
      padding: '20px',
      backgroundColor: '#1a1a1a',
      color: '#ffffff',
      fontFamily: 'Courier New, monospace',
      minHeight: '100vh'
    }}>
      <h3 style={{color: '#00ff00'}}>Architecture Structure</h3>
      <p>Component is rendering!</p>
      <p>Data received: {data ? `Array with ${data.length} items` : 'No data'}</p>
      
      {data && data.length > 0 ? (
        <div>
          <h4>Data found:</h4>
          <pre style={{color: 'yellow', fontSize: '12px'}}>
            {JSON.stringify(data, null, 2)}
          </pre>
        </div>
      ) : (
        <div>
          <h4>No Architecture Data</h4>
          <p>Create some deployment units to see the architecture</p>
          <code style={{backgroundColor: '#333', padding: '4px'}}>du-online "MyApp"</code>
        </div>
      )}
    </div>
  );
};

export default HierarchicalRenderer;
